cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# Generate candidate square and L triominoes within cells
from itertools import combinations
Ls=[]
for r in range(6):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for omit in box:
   shape=box-{omit}
   if shape<=cells: Ls.append(shape)
squares=[]
for r in range(6):
 for c in range(6):
  sh={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sh<=cells:squares.append(sh)
print(len(cells),len(squares),len(Ls),[sorted(x) for x in squares])
solutions=[]
def rec(rem, chosen):
 if not rem:
  solutions.append(chosen);return
 x=min(rem)
 for sh in squares+Ls:
  if x in sh and sh<=rem:
   rec(rem-sh,chosen+[sh])
rec(cells,[])
print('solutions',len(solutions))
print([[len(s) for s in sol] for sol in solutions[:10]])

for sol in solutions:
 for sh in sol:
  print(len(sh),sorted(sh), 'bbox', (min(r for r,c in sh),max(r for r,c in sh),min(c for r,c in sh),max(c for r,c in sh)))
